//! NIST FIPS 204 ML-DSA-65 Known-Answer-Test (KAT) anchors — tier 1.
//!
//! Externally-anchored validation per CLAUDE.md's golden rule: the vectors
//! below (seed, public key, private key, message, signature) are taken
//! verbatim from the NIST CAVP / ACVP-Server gen-val reference set, NOT from
//! this implementation. They prove ml_dsa.zig produces byte-identical output
//! to the FIPS 204 standard, deterministically.
//!
//! Source: https://github.com/usnistgov/ACVP-Server
//!   gen-val/json-files/ML-DSA-keyGen-FIPS204/internalProjection.json  (ML-DSA-65, tcId 26)
//!   gen-val/json-files/ML-DSA-sigGen-FIPS204/internalProjection.json  (ML-DSA-65, tgId 10 = deterministic / internal / externalMu=false, tcId 136)
//!
//! ml_dsa.sign(sk, msg, randomized=false) implements FIPS 204 Sign_internal
//! (mu = H(tr || msg), rnd = 0), which is exactly the ACVP "internal /
//! deterministic / externalMu=false" interface used here.

const std = @import("std");
const ml_dsa = @import("ml_dsa.zig");

// ---- keyGen vector: seed -> (pk, sk) ----
const kg_seed_hex = "1BD67DC782B2958E189E315C040DD1F64C8AB232A6A170E1A7A52C33F10851B1";
const kg_pk_hex = "";
const kg_sk_hex = "";

// ---- sigGen vector: (sk, message) -> signature  [+ pk for verify] ----
const sg_sk_hex = "";
const sg_pk_hex = "";
const sg_msg_hex = "";
const sg_sig_hex = "";

fn hexAlloc(a: std.mem.Allocator, hex: []const u8) ![]u8 {
    const out = try a.alloc(u8, hex.len / 2);
    errdefer a.free(out);
    _ = try std.fmt.hexToBytes(out, hex);
    return out;
}

test "NIST FIPS 204 KAT: ML-DSA-65 keyGen (seed -> pk, sk)" {
    var seed: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&seed, kg_seed_hex);

    const kp = ml_dsa.keyGen(&seed);

    var exp_pk: [ml_dsa.PUBLIC_KEY_SIZE]u8 = undefined;
    var exp_sk: [ml_dsa.SECRET_KEY_SIZE]u8 = undefined;
    _ = try std.fmt.hexToBytes(&exp_pk, kg_pk_hex);
    _ = try std.fmt.hexToBytes(&exp_sk, kg_sk_hex);

    try std.testing.expectEqualSlices(u8, &exp_pk, &kp.pk.data);
    try std.testing.expectEqualSlices(u8, &exp_sk, &kp.sk.data);
}

test "NIST FIPS 204 KAT: ML-DSA-65 sigGen (sk, msg -> sig, deterministic)" {
    const a = std.testing.allocator;

    var sk: ml_dsa.SecretKey = undefined;
    _ = try std.fmt.hexToBytes(&sk.data, sg_sk_hex);

    const msg = try hexAlloc(a, sg_msg_hex);
    defer a.free(msg);

    const sig = ml_dsa.sign(&sk, msg, false) orelse return error.SigningFailed;

    var exp_sig: [ml_dsa.SIGNATURE_SIZE]u8 = undefined;
    _ = try std.fmt.hexToBytes(&exp_sig, sg_sig_hex);

    try std.testing.expectEqualSlices(u8, &exp_sig, &sig.data);
}

test "NIST FIPS 204 KAT: ML-DSA-65 verify (pk, msg, sig -> accept)" {
    const a = std.testing.allocator;

    var pk: ml_dsa.PublicKey = undefined;
    _ = try std.fmt.hexToBytes(&pk.data, sg_pk_hex);

    var sig: ml_dsa.Signature = undefined;
    _ = try std.fmt.hexToBytes(&sig.data, sg_sig_hex);

    const msg = try hexAlloc(a, sg_msg_hex);
    defer a.free(msg);

    try std.testing.expect(ml_dsa.verify(&pk, msg, &sig));
}
